Shader "Hidden/OutterLineAdd" {
Properties {
	_MainTex ("", 2D) = "white" {}
	_Color("MainColor",Color)=(1,1,1,1)
}
Category {
	ZTest Always Cull Off ZWrite Off Fog { Mode Off }
	Blend SrcAlpha OneMinusSrcAlpha
	SubShader {
		Pass {
			SetTexture [_MainTex] {constantColor [_Color] combine constant * texture}
		}
	}
}
Fallback off
